-- MesaPOS · verificación POSTERIOR a 08 y 09 (SOLO LECTURA; no modifica nada). Ejecutar tras aplicar cada paso y anotar el resultado.
-- Esperado tras 08: filas 1-4 ok. Tras 09: todas ok. Histórico intacto: fila 9 igual al valor anotado antes (verificar_08_previo.sql fila 'ventas').
select o, qué, valor, esperado from (
 select 1 o, '08: tablas de turno (aperturas_caja v2 + cobros_turno, movimientos_caja, cierres_turno, cierres_turno_medios, turno_eventos)' qué,
   (select count(*) from information_schema.tables where table_schema='public' and table_name in ('cobros_turno','movimientos_caja','cierres_turno','cierres_turno_medios','turno_eventos'))::text valor, '5' esperado
 union all select 2, '08: turno_bloqueos y funciones de turno', (select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and proname in ('turno_bloqueos','turno_abrir','turno_resumen','turno_cerrar'))::text, '4'
 union all select 3, '08: triggers de caja', (select count(*) from pg_trigger where not tgisinternal and tgname in ('ventas_serializa_cierre','ventas_eliminada_anula_cobros','pagos_point_turno_abierto','ventas_cobro_a_turno','gastos_a_turno','propinas_a_turno','aperturas_v2_guard'))::text, '7'
 union all select 4, '08: cierre revisa bloqueos en el servidor', coalesce((select (pg_get_functiondef(p.oid) like '%turno_bloqueos%')::text from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and proname='turno_cerrar'),'falta'), 'true'
 union all select 5, '09: tabla correlativos', (select count(*) from information_schema.tables where table_schema='public' and table_name='correlativos')::text, '1'
 union all select 6, '09: columnas folio, clave_idempotencia, numero_turno, clave_apertura, numero_cierre', (select count(*) from information_schema.columns where table_schema='public' and ((table_name='ventas' and column_name in ('folio','clave_idempotencia')) or (table_name='aperturas_caja' and column_name in ('numero_turno','clave_apertura')) or (table_name='cierres_turno' and column_name='numero_cierre')))::text, '5'
 union all select 7, '09: turno_abrir con clave (4 argumentos) y trigger de folio', coalesce((select pg_get_function_identity_arguments(p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and proname='turno_abrir'),'falta') || ' / trigger ventas_folio=' || (select count(*) from pg_trigger where tgname='ventas_folio' and not tgisinternal)::text, 'p_empresa uuid, p_fondo integer, p_cajero text, p_clave uuid / trigger ventas_folio=1'
 union all select 8, '09: índices únicos de folio y claves', (select count(*) from pg_indexes where schemaname='public' and indexname in ('ventas_folio_uq','ventas_clave_uq','aperturas_numero_turno_uq','aperturas_clave_uq','cierres_numero_uq'))::text, '5'
 union all select 9, '09: histórico sin folio (comandas existentes con folio asignado por 09; debe ser 0 justo tras aplicar)', (select count(*) from public.ventas where folio is not null)::text, '0 (solo antes de la primera comanda nueva)'
 union all select 10, '09: contadores por negocio (tipo:último; comanda = mayor número histórico)', coalesce((select string_agg(left(empresa_id::text,8)||' '||tipo||':'||ultimo, ', ' order by empresa_id, tipo) from public.correlativos),'(vacío)'), 'comanda = máximo histórico por negocio'
 union all select 11, '09: permisos restringidos (anon/authenticated sin acceso a correlativos ni a correlativo_siguiente)', (not has_table_privilege('anon','public.correlativos','select') and not has_table_privilege('authenticated','public.correlativos','select') and not has_function_privilege('anon','public.correlativo_siguiente(uuid,text)','execute') and not has_function_privilege('authenticated','public.correlativo_siguiente(uuid,text)','execute'))::text, 'true'
 union all select 12, 'turnos abiertos ahora (debe ser 0 antes de la ventana; 0 al terminar la ventana)', (select count(*) from public.aperturas_caja where estado='abierta')::text, '0'
) q order by o;
